/// The coordinator ties together EC, storage, and metadata.
struct ReclaimSweeper {
    storage_node: Arc<SharedStorageNode>,
    stop: Arc<AtomicBool>,
    handle: Option<JoinHandle<()>>,
}

struct LifecycleSweeper {
    stop: Arc<AtomicBool>,
    handle: Mutex<Option<JoinHandle<()>>>,
}

#[derive(Debug, Clone)]
struct CachedBucketPolicy {
    generation: u64,
    policy: Arc<auth::BucketPolicy>,
}

#[derive(Debug, Clone)]
struct CachedBucketLifecycle {
    generation: u64,
    config: Arc<BucketLifecycleConfiguration>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct LifecycleSweepStats {
    scanned_buckets: u64,
    expired_current_objects: u64,
    expired_noncurrent_versions: u64,
    expired_delete_markers: u64,
    aborted_multipart_uploads: u64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DeletedLiveObjectKind {
    Segments,
    Multipart,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct DeletedLiveObjectReclaim {
    generation_id: GenerationId,
    kind: DeletedLiveObjectKind,
}

enum ObjectAclAuthorization {
    ReadWithPolicy(auth::PolicyAction),
    Write,
}

impl Drop for ReclaimSweeper {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::SeqCst);
        self.storage_node.wake_reclaim_workers();
        if let Some(handle) = self.handle.take() {
            let _ = handle.join();
        }
    }
}

impl Drop for LifecycleSweeper {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::SeqCst);
        if let Some(handle) = lock_mutex_unpoisoned(&self.handle).take() {
            let _ = handle.join();
        }
    }
}

impl LifecycleSweeper {
    fn acquire_shared(
        storage_node: &Arc<SharedStorageNode>,
        runtime: ReadRuntime,
    ) -> Result<Arc<Self>, ServerError> {
        let registry = LIFECYCLE_SWEEPER_REGISTRY.get_or_init(|| Mutex::new(HashMap::new()));
        let mut registry = lock_mutex_unpoisoned(registry);
        registry.retain(|_, sweeper| sweeper.upgrade().is_some());

        let key = Arc::as_ptr(storage_node) as usize;
        if let Some(existing) = registry.get(&key).and_then(Weak::upgrade) {
            return Ok(existing);
        }

        let sweeper = Self::spawn(runtime)?;
        registry.insert(key, Arc::downgrade(&sweeper));
        Ok(sweeper)
    }

    fn spawn(runtime: ReadRuntime) -> Result<Arc<Self>, ServerError> {
        let stop = Arc::new(AtomicBool::new(false));
        let sweeper = Arc::new(Self {
            stop: Arc::clone(&stop),
            handle: Mutex::new(None),
        });
        let handle = std::thread::Builder::new()
            .name("argmin-lifecycle".to_string())
            .spawn(move || {
                while !stop.load(Ordering::SeqCst) {
                    let _ = runtime.run_lifecycle_sweep_at(Coordinator::now_millis());
                    let mut remaining = LIFECYCLE_SWEEP_INTERVAL_MILLIS;
                    while remaining > 0 && !stop.load(Ordering::SeqCst) {
                        let step = remaining.min(100);
                        std::thread::sleep(std::time::Duration::from_millis(step));
                        remaining -= step;
                    }
                }
            })
            .map_err(|e| ServerError::InternalError {
                reason: format!("failed to start lifecycle worker: {e}"),
            })?;
        *lock_mutex_unpoisoned(&sweeper.handle) = Some(handle);
        Ok(sweeper)
    }

    #[cfg(test)]
    fn disabled() -> Arc<Self> {
        Arc::new(Self {
            stop: Arc::new(AtomicBool::new(true)),
            handle: Mutex::new(None),
        })
    }
}

pub struct Coordinator {
    storage_node: Arc<SharedStorageNode>,
    bucket_policy_cache: RwLock<HashMap<String, CachedBucketPolicy>>,
    bucket_lifecycle_cache: RwLock<HashMap<String, CachedBucketLifecycle>>,
    pg_topology: PgTopology,
    ec_codec: Arc<ErasureCodec>,
    ec_config: EcConfig,
    encode_scratch_pool: EncodeScratchPool,
    payload_buffer_pool: Arc<PayloadBufferPool>,
    region: String,
    sse_c_validator: Option<SseCustomerValidatorConfig>,
    managed_key_provider: Option<StaticManagedKeyProvider>,
    _reclaim_sweeper: ReclaimSweeper,
    _lifecycle_sweeper: Arc<LifecycleSweeper>,
}

