    fn requested_version_is_current_live(
        meta_pg: &storage::PgStore,
        bucket: &str,
        key: &str,
        requested_version_id: Option<VersionId>,
        resolved_version_id: VersionId,
    ) -> Result<bool, ServerError> {
        if requested_version_id.is_none() {
            return Ok(true);
        }
        let _ = (meta_pg, bucket, key, resolved_version_id);
        Ok(false)
    }

    fn evaluate_current_object_lifecycle_expiration(
        config: &BucketLifecycleConfiguration,
        key: &str,
        tags: &[(String, String)],
        size: u64,
        last_modified: u64,
    ) -> Option<LifecycleExpirationHeader> {
        let mut best = None;

        for rule in &config.rules {
            if rule.status != LifecycleRuleStatus::Enabled
                || !rule.filter.matches_object(key, tags, size)
            {
                continue;
            }
            let Some(expiration) = &rule.expiration else {
                continue;
            };
            let expiry_time_millis = match expiration {
                LifecycleExpiration::Days(days) => {
                    Self::lifecycle_day_based_deadline(last_modified, days.get())?
                }
                LifecycleExpiration::Date(date) => Self::lifecycle_date_deadline(*date)?,
                LifecycleExpiration::ExpiredObjectDeleteMarker => continue,
            };
            let candidate = LifecycleExpirationHeader {
                expiry_time_millis,
                rule_id: rule.id.clone(),
            };
            if best
                .as_ref()
                .is_none_or(|current: &LifecycleExpirationHeader| {
                    candidate.expiry_time_millis < current.expiry_time_millis
                })
            {
                best = Some(candidate);
            }
        }

        best
    }

    fn evaluate_due_noncurrent_version_expirations(
        config: &BucketLifecycleConfiguration,
        versions: &[StoredObject],
        now_millis: u64,
    ) -> Result<Vec<NoncurrentLifecycleExpiration>, ServerError> {
        #[derive(Debug)]
        struct NoncurrentVersionCandidate {
            version_id: VersionId,
            tags: Vec<(String, String)>,
            size: u64,
            became_noncurrent_at: u64,
        }

        if versions.len() <= 1 {
            return Ok(Vec::new());
        }

        let key = versions[0].key().as_str();
        let mut candidates = Vec::new();
        for stored in versions.iter().skip(1) {
            let Some(record) = stored.as_live() else {
                continue;
            };
            let Some(became_noncurrent_at) = record.became_noncurrent_at else {
                continue;
            };
            let tags = match record.tags.as_deref() {
                Some(tags_xml) => Self::parse_serialized_tag_set(tags_xml)?,
                None => Vec::new(),
            };
            candidates.push(NoncurrentVersionCandidate {
                version_id: record.version_id,
                tags,
                size: record.size,
                became_noncurrent_at,
            });
        }
        if candidates.is_empty() {
            return Ok(Vec::new());
        }

        let mut due_by_version: HashMap<VersionId, u64> = HashMap::new();
        for rule in &config.rules {
            if rule.status != LifecycleRuleStatus::Enabled {
                continue;
            }
            let Some(noncurrent) = &rule.noncurrent_version_expiration else {
                continue;
            };

            let mut newer_matching_noncurrent_versions = 0u32;
            for candidate in &candidates {
                if !rule
                    .filter
                    .matches_object(key, &candidate.tags, candidate.size)
                {
                    continue;
                }

                let Some(expiry_time_millis) = Self::lifecycle_day_based_deadline(
                    candidate.became_noncurrent_at,
                    noncurrent.noncurrent_days.get(),
                ) else {
                    continue;
                };
                let retain_newer = noncurrent
                    .newer_noncurrent_versions
                    .map_or(0, std::num::NonZeroU32::get);

                if newer_matching_noncurrent_versions >= retain_newer
                    && expiry_time_millis <= now_millis
                {
                    due_by_version
                        .entry(candidate.version_id)
                        .and_modify(|current| {
                            *current = (*current).min(expiry_time_millis);
                        })
                        .or_insert(expiry_time_millis);
                }

                // The retention count applies to newer noncurrent versions that
                // are in scope for the same rule.
                newer_matching_noncurrent_versions += 1;
            }
        }

        let mut due = Vec::new();
        for candidate in candidates {
            if let Some(expiry_time_millis) = due_by_version.remove(&candidate.version_id) {
                due.push(NoncurrentLifecycleExpiration {
                    version_id: candidate.version_id,
                    expiry_time_millis,
                });
            }
        }
        Ok(due)
    }

    fn evaluate_due_expired_delete_marker(
        config: &BucketLifecycleConfiguration,
        versions: &[StoredObject],
        now_millis: u64,
    ) -> Option<DeleteMarkerLifecycleExpiration> {
        let StoredObject::DeleteMarker(marker) = versions.first()? else {
            return None;
        };
        if versions.len() != 1 {
            return None;
        }

        let mut best = None;
        for rule in &config.rules {
            if rule.status != LifecycleRuleStatus::Enabled
                || !Self::lifecycle_rule_matches_delete_marker(rule, marker.key.as_str())
            {
                continue;
            }

            let Some(expiration) = &rule.expiration else {
                continue;
            };
            let expiry_time_millis = match expiration {
                LifecycleExpiration::Days(days) => {
                    Self::lifecycle_day_based_deadline(marker.last_modified, days.get())?
                }
                LifecycleExpiration::Date(date) => Self::lifecycle_date_deadline(*date)?,
                LifecycleExpiration::ExpiredObjectDeleteMarker => 0,
            };

            if expiry_time_millis > now_millis {
                continue;
            }

            let candidate = DeleteMarkerLifecycleExpiration {
                version_id: marker.version_id,
                expiry_time_millis,
            };
            if best
                .as_ref()
                .is_none_or(|current: &DeleteMarkerLifecycleExpiration| {
                    candidate.expiry_time_millis < current.expiry_time_millis
                })
            {
                best = Some(candidate);
            }
        }

        best
    }

    fn evaluate_multipart_lifecycle_abort_headers(
        config: &BucketLifecycleConfiguration,
        key: &str,
        initiated_at: u64,
    ) -> Option<LifecycleAbortHeaders> {
        let mut best = None;

        for rule in &config.rules {
            if rule.status != LifecycleRuleStatus::Enabled
                || !rule.filter.matches_multipart_upload(key)
            {
                continue;
            }
            let Some(abort) = &rule.abort_incomplete_multipart_upload else {
                continue;
            };
            let abort_time_millis = Self::lifecycle_day_based_deadline(
                initiated_at,
                abort.days_after_initiation.get(),
            )?;
            let candidate = LifecycleAbortHeaders {
                abort_time_millis,
                rule_id: rule.id.clone(),
            };
            if best.as_ref().is_none_or(|current: &LifecycleAbortHeaders| {
                candidate.abort_time_millis < current.abort_time_millis
            }) {
                best = Some(candidate);
            }
        }

        best
    }

    fn lifecycle_rule_matches_delete_marker(rule: &LifecycleRule, key: &str) -> bool {
        !rule.filter.has_tag_filter()
            && !rule.filter.has_size_filter()
            && rule
                .filter
                .prefix
                .as_ref()
                .is_none_or(|prefix| key.starts_with(prefix))
    }

    fn lifecycle_day_based_deadline(start_millis: u64, days: u32) -> Option<u64> {
        let start_day = start_millis / 86_400_000;
        start_day
            .checked_add(u64::from(days))?
            .checked_add(1)?
            .checked_mul(86_400_000)
    }

    fn lifecycle_date_deadline(date: LifecycleDate) -> Option<u64> {
        let days = u64::try_from(date.days_since_epoch()).ok()?;
        days.checked_mul(86_400_000)
    }

    fn bucket_policy_decision_for_object(
        requester: &Requester,
        bucket: &BucketSummary,
        object: &StoredObject,
        action: auth::PolicyAction,
        policy: Option<&auth::BucketPolicy>,
    ) -> Result<auth::PolicyEvaluation, ServerError> {
        let Some(policy) = policy else {
            return Ok(auth::PolicyEvaluation::NoMatch);
        };

        let existing_tags = if policy.requires_existing_object_tags_for_action(action) {
            Self::parse_policy_existing_object_tags(object)?
        } else {
            Vec::new()
        };
        let request_tags: Vec<auth::PolicyTag<'_>> = existing_tags
            .iter()
            .map(|(key, value)| auth::PolicyTag::new(key, value))
            .collect();
        let request = auth::PolicyRequest::new(
            action,
            &bucket.name,
            object.key().as_str(),
            requester.principal_opt(),
            requester.canonical_user_id(),
        );
        let request = request.with_existing_object_tags(&request_tags);
        Ok(policy.evaluate(&request))
    }

    fn bucket_policy_decision_for_key(
        requester: &Requester,
        bucket: &BucketSummary,
        key: &str,
        action: auth::PolicyAction,
        policy: Option<&auth::BucketPolicy>,
    ) -> auth::PolicyEvaluation {
        let Some(policy) = policy else {
            return auth::PolicyEvaluation::NoMatch;
        };

        let request = auth::PolicyRequest::new(
            action,
            &bucket.name,
            key,
            requester.principal_opt(),
            requester.canonical_user_id(),
        );
        policy.evaluate(&request)
    }

    fn bucket_policy_decision_for_bucket(
        requester: &Requester,
        bucket: &BucketSummary,
        action: auth::PolicyAction,
        policy: Option<&auth::BucketPolicy>,
    ) -> auth::PolicyEvaluation {
        let Some(policy) = policy else {
            return auth::PolicyEvaluation::NoMatch;
        };

        let request = auth::PolicyRequest::for_bucket(
            action,
            &bucket.name,
            requester.principal_opt(),
            requester.canonical_user_id(),
        );
        policy.evaluate(&request)
    }

    fn bucket_policy_decision_for_put_object_action(
        requester: &Requester,
        bucket: &BucketSummary,
        key: &str,
        action: auth::PolicyAction,
        policy_context: PutObjectPolicyContext<'_>,
        policy: Option<&auth::BucketPolicy>,
    ) -> Result<auth::PolicyEvaluation, ServerError> {
        let Some(policy) = policy else {
            return Ok(auth::PolicyEvaluation::NoMatch);
        };

        let request_object_tags = if policy.requires_request_object_tags_for_action(action) {
            match policy_context.request_object_tags_xml {
                Some(tags_xml) => Self::parse_serialized_tag_set(tags_xml)?,
                None => Vec::new(),
            }
        } else {
            Vec::new()
        };
        let request_object_tags: Vec<auth::PolicyTag<'_>> = request_object_tags
            .iter()
            .map(|(tag_key, value)| auth::PolicyTag::new(tag_key, value))
            .collect();
        let request = auth::PolicyRequest::new(
            action,
            &bucket.name,
            key,
            requester.principal_opt(),
            requester.canonical_user_id(),
        )
        .with_request_object_tags(&request_object_tags)
        .with_copy_source(policy_context.copy_source)
        .with_metadata_directive(policy_context.metadata_directive)
        .with_canned_acl(policy_context.canned_acl)
        .with_server_side_encryption(
            policy_context
                .managed_encryption
                .map(ManagedEncryptionAlgorithm::as_str),
        )
        .with_sse_customer_algorithm(policy_context.sse_customer_algorithm)
        .with_grant_read(policy_context.grant_read)
        .with_grant_write(policy_context.grant_write)
        .with_grant_read_acp(policy_context.grant_read_acp)
        .with_grant_write_acp(policy_context.grant_write_acp)
        .with_grant_full_control(policy_context.grant_full_control);
        Ok(policy.evaluate(&request))
    }

    fn requester_can_put_object_action_with_bucket_policy(
        requester: &Requester,
        bucket: &BucketSummary,
        key: &str,
        action: auth::PolicyAction,
        policy_context: PutObjectPolicyContext<'_>,
        policy: Option<&auth::BucketPolicy>,
        default_allowed: bool,
    ) -> Result<bool, ServerError> {
        Ok(
            match Self::bucket_policy_decision_for_put_object_action(
                requester,
                bucket,
                key,
                action,
                policy_context,
                policy,
            )? {
                auth::PolicyEvaluation::ExplicitDeny => false,
                auth::PolicyEvaluation::ExplicitAllow
                    if Self::bucket_policy_allow_survives_restrict_public_buckets(
                        requester, bucket,
                    ) =>
                {
                    true
                }
                auth::PolicyEvaluation::ExplicitAllow | auth::PolicyEvaluation::NoMatch => {
                    default_allowed
                }
            },
        )
    }

    fn requester_can_read_object_with_bucket_policy(
        requester: &Requester,
        bucket: &BucketSummary,
        object: &StoredObject,
        action: auth::PolicyAction,
        policy: Option<&auth::BucketPolicy>,
    ) -> Result<bool, ServerError> {
        Ok(
            match Self::bucket_policy_decision_for_object(
                requester, bucket, object, action, policy,
            )? {
                auth::PolicyEvaluation::ExplicitDeny => false,
                auth::PolicyEvaluation::ExplicitAllow
                    if Self::bucket_policy_allow_survives_restrict_public_buckets(
                        requester, bucket,
                    ) =>
                {
                    true
                }
                auth::PolicyEvaluation::ExplicitAllow | auth::PolicyEvaluation::NoMatch => {
                    Self::requester_can_read_object(requester, bucket, object)
                }
            },
        )
    }

