    pub fn put_object_tags(&self, req: &PutObjectTagsRequest<'_>) -> Result<(), ServerError> {
        observability::trace_scope!(
            TRACE_TARGET,
            "Coordinator::put_object_tags",
            "bucket={} key={} bytes={}",
            req.object.bucket_name(),
            req.object.key(),
            req.tags.len()
        );
        let LockedReadObject {
            record: stored,
            pgs,
        } = self.lock_object_for_authorized_tagging(
            req.object.requester(),
            req.object.bucket_name(),
            req.object.key(),
            req.object.version_id,
            Self::put_object_tagging_policy_action(req.object.version_id),
            req.object.expected_bucket_owner(),
        )?;
        if stored.is_delete_marker() {
            return Err(ServerError::MethodNotAllowed);
        }
        pgs.meta()
            .put_object_tags(
                req.object.bucket_name(),
                req.object.key(),
                stored.version_id(),
                req.tags,
            )
            .map_err(ServerError::Metadata)
    }

    pub fn put_object_retention(
        &self,
        req: &PutObjectRetentionRequest<'_>,
    ) -> Result<(), ServerError> {
        observability::trace_scope!(
            TRACE_TARGET,
            "Coordinator::put_object_retention",
            "bucket={} key={} version_id={:?} mode={:?} bypass={}",
            req.object.bucket_name(),
            req.object.key(),
            req.object.version_id,
            req.retention.mode,
            req.bypass_governance
        );
        let (
            bucket_info,
            bucket_policy,
            LockedReadObject {
                record: stored,
                pgs,
            },
        ) = self.lock_object_for_authorized_object_lock(
            req.object.requester(),
            req.object.bucket_name(),
            req.object.key(),
            req.object.version_id,
            auth::PolicyAction::PutObjectRetention,
            req.object.expected_bucket_owner(),
        )?;
        let live = stored.as_live().ok_or(ServerError::MethodNotAllowed)?;
        let can_bypass_governance =
            Self::requester_can_bypass_governance_retention_with_bucket_policy(
                req.object.requester(),
                &bucket_info,
                &stored,
                bucket_policy.as_deref(),
            )?;
        Self::validate_retention_update(
            live.object_lock.retention,
            req.retention,
            req.bypass_governance,
            can_bypass_governance,
        )?;
        pgs.meta()
            .put_object_retention(
                req.object.bucket_name(),
                req.object.key(),
                live.version_id,
                req.retention,
            )
            .map_err(|e| match e {
                storage::MetadataError::MethodNotAllowedOnDeleteMarker => {
                    ServerError::MethodNotAllowed
                }
                other => ServerError::Metadata(other),
            })
    }

    pub fn get_object_retention(
        &self,
        req: &ObjectVersionRequest<'_>,
    ) -> Result<Option<ObjectRetention>, ServerError> {
        observability::trace_scope!(
            TRACE_TARGET,
            "Coordinator::get_object_retention",
            "bucket={} key={} version_id={:?}",
            req.object.bucket_name(),
            req.object.key,
            req.version_id
        );
        let (_bucket_info, _bucket_policy, LockedReadObject { record: stored, .. }) = self
            .lock_object_for_authorized_object_lock(
                req.object.requester(),
                req.object.bucket_name(),
                req.object.key,
                req.version_id,
                auth::PolicyAction::GetObjectRetention,
                req.expected_bucket_owner(),
            )?;
        let live = stored.as_live().ok_or(ServerError::MethodNotAllowed)?;
        Ok(live.object_lock.retention)
    }

