    #[test]
    fn put_object_acl_updates_only_requested_version() {
        let tmp = test_util::tempdir();
        let coord = setup_coordinator(tmp.path());
        let owner = AccountIdentity::new(
            "owner-a",
            CanonicalUserId::from_principal("owner-version-canonical"),
            "Owner A",
        );
        let requester = Requester::authenticated(owner);

        coord
            .create_bucket(&CreateBucketRequest {
                name: "bucket",
                requester: requester.clone(),
                namespace: BucketNamespace::Global,
                acl: CreateBucketAcl::DefaultPrivate,
                ownership: BucketObjectOwnership::ObjectWriter,
                object_lock_enabled: false,
            })
            .unwrap();
        put_bucket_versioning_test(
            &coord,
            "bucket",
            BucketVersioningState::Enabled,
            requester.clone(),
            None,
        )
        .unwrap();

        let v1 = test_helpers::put_object(
            &coord,
            &PutObjectRequest {
                encryption: WriteEncryptionRequest::none(),
                policy_context: PutObjectPolicyContext::default(),
                object_lock: ObjectLockState::default(),
                object: object_request_with_expected_owner(
                    "bucket",
                    "key",
                    requester.clone(),
                    None,
                ),
                data: b"v1",
                metadata: &MetadataBlob::new(),
                system_metadata: &SystemMetadata::EMPTY,
                tags: None,
                cond: NO_WRITE,

                acl: NO_PUT_OBJECT_ACL.into(),
            },
        )
        .unwrap();
        let v2 = test_helpers::put_object(
            &coord,
            &PutObjectRequest {
                encryption: WriteEncryptionRequest::none(),
                policy_context: PutObjectPolicyContext::default(),
                object_lock: ObjectLockState::default(),
                object: object_request_with_expected_owner(
                    "bucket",
                    "key",
                    requester.clone(),
                    None,
                ),
                data: b"v2",
                metadata: &MetadataBlob::new(),
                system_metadata: &SystemMetadata::EMPTY,
                tags: None,
                cond: NO_WRITE,

                acl: NO_PUT_OBJECT_ACL.into(),
            },
        )
        .unwrap();

        put_object_canned_acl_test(
            &coord,
            "bucket",
            "key",
            Some(v1.version_id),
            PutObjectAcl::PublicRead,
            requester.clone(),
            None,
        )
        .unwrap();

        let v1_acl = get_object_acl_test(
            &coord,
            "bucket",
            "key",
            Some(v1.version_id),
            requester.clone(),
            None,
        )
        .unwrap();
        let v2_acl = get_object_acl_test(
            &coord,
            "bucket",
            "key",
            Some(v2.version_id),
            requester.clone(),
            None,
        )
        .unwrap();
        assert!(grants_contain(
            &v1_acl.acl_grants,
            &AclGrantee::AllUsers,
            AclPermission::Read,
        ));
        assert!(!grants_contain(
            &v2_acl.acl_grants,
            &AclGrantee::AllUsers,
            AclPermission::Read,
        ));
    }

