    #[test]
    fn complete_multipart_upload_retry_after_validation_failure() {
        let tmp = test_util::tempdir();
        let coord = setup_coordinator(tmp.path());
        coord
            .create_bucket_for_owner("default-owner", "bucket", false)
            .unwrap();

        // Upload two small parts.
        let (upload_id, parts) =
            create_upload_with_parts(&coord, "bucket", "key", &[(1, b"small"), (2, b"last")]);

        // First attempt fails because part 1 is too small.
        let err = coord
            .complete_multipart_upload(&CompleteMultipartUploadRequest {
                upload: multipart_object_request_with_expected_owner(
                    "bucket",
                    "key",
                    &upload_id,
                    test_requester(),
                    None,
                ),
                parts: &parts,
                claimed_checksum: None,

                cond: &WriteCondition::default(),

                sse_customer: None,
            })
            .unwrap_err();
        assert!(matches!(err, ServerError::EntityTooSmall { .. }));

        // Upload remains usable — re-upload part 1 with large data and retry.
        let big_data = vec![0u8; 5 * 1024 * 1024];
        let new_part1 = test_helpers::upload_part(
            &coord,
            &UploadPartRequest {
                upload: multipart_object_request_with_expected_owner(
                    "bucket",
                    "key",
                    &upload_id,
                    test_requester(),
                    None,
                ),
                part_number: 1,
                data: &big_data,
                claimed_checksum: None,

                sse_customer: None,
            },
        )
        .unwrap();

        let retry_parts = vec![
            CompletePart {
                part_number: 1,
                etag: new_part1.etag,
                checksum: None,
            },
            parts[1].clone(),
        ];
        let result = coord
            .complete_multipart_upload(&CompleteMultipartUploadRequest {
                upload: multipart_object_request_with_expected_owner(
                    "bucket",
                    "key",
                    &upload_id,
                    test_requester(),
                    None,
                ),
                parts: &retry_parts,
                claimed_checksum: None,

                cond: &WriteCondition::default(),

                sse_customer: None,
            })
            .unwrap();
        assert!(result.etag.ends_with("-2\""));
    }

